void div_mult_axis(axis_scale_t *as, uint8_t div) {
    if (div != 0) {
        uint8_t new_mult = as->mult / div;
        if (new_mult == 0) {
            new_mult = 1;
        }
        as->remainder /= div;
        as->mult = new_mult;
    }
